{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Konklusionen om at arbejdsophør ikke i sig selv giver ret til tillægget stemmer med rubrikken og vejledningen. Beskrivelsen af Udbetaling Danmarks vurdering af andre arbejdstyper, skånehensyn eller mindre omfang og skånebehov er korrekt. Der er ingen væsentlige juridiske fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret nævner andre typer arbejde med skånehensyn eller mindre omfang. Det nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen, og heller ikke, at vurderingen sker ud fra sagens øvrige oplysninger. Dermed mangler to af de tre kritiske elementer."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer begge dele af spørgsmålet: Nej, ophøret giver ikke i sig selv ret, og det forklarer, hvad Udbetaling Danmark vurderer."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse eller vejledningsafsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildestøtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen regler, betingelser eller myndigheder ud over det, der står i vejledningsafsnit 3.4.1.3. Udsagnene om andre arbejdstyper, skånehensyn, mindre omfang og skånebehov følger af materialet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret fastholder, at ophøret ikke i sig selv afgør retten, men indgår i en nærmere vurdering. Eksemplet med ikke-fysisk belastende arbejde udelades, og det er tilladt. Det gør heller ikke eksemplet til en betingelse."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Konklusionen om, at ophøret ikke i sig selv giver ret, følger af den beskrevne vurdering. Der er ingen indre modsigelser."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "Svaret gengiver vurderingen præcist ('vurderer om', 'evt.') og gør ikke skøn eller eksempler til absolutte regler."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret dækker, at ansøgeren er ophørt i arbejde på grund af funktionsnedsættelsen, og at der vurderes andre arbejdstyper, skånehensyn og skånebehov. Det udelader, at arbejdets karakter ses i forhold til funktionsnedsættelsen, og at sagens øvrige oplysninger indgår. Eksemplet med ikke-fysisk belastende arbejde mangler også."
    },
    "A23": {
      "label": "yes",
      "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren kan varetage andre typer arbejde, evt. med skånehensyn eller i mindre omfang."
    }
  },
  "overall_notes": "Svaret er juridisk korrekt og relevant, men uden kildehenvisning. Det udelader to kritiske elementer: sammenholdelsen af arbejdets karakter med funktionsnedsættelsen og brugen af sagens øvrige oplysninger."
}

